function parseCookiePairs(str){
  return String(str||'').split(';').map(function(p){
    p=p.trim(); if(!p) return null;
    var i=p.indexOf('=');
    if(i<0) return {name:p, value:''};
    return {name:p.slice(0,i).trim(), value:p.slice(i+1).trim()};
  }).filter(Boolean);
}
function parseSetCookie(str){
  var parts=String(str||'').split(';');
  var first=parts[0]||'';
  var eq=first.indexOf('=');
  var name= eq<0? '' : first.slice(0,eq).trim();
  var value= eq<0? first.trim() : first.slice(eq+1).trim();
  var attrs={}, issues=[], warnings=[];
  for(var i=1;i<parts.length;i++){
    var p=parts[i].trim(); if(!p) continue;
    var j=p.indexOf('=');
    var k=(j<0?p:p.slice(0,j)).trim();
    var v=j<0?'':p.slice(j+1).trim();
    var kl=k.toLowerCase();
    if(kl==='expires'){
      attrs.expires=v;
      var t=Date.parse(v);
      if(isNaN(t)){ issues.push('Expires 无法解析为合法日期'); attrs.expiresTs=null; }
      else attrs.expiresTs=t;
    } else if(kl==='max-age'){
      attrs.maxAge=v;
      if(!/^-?\d+$/.test(v)){ issues.push('Max-Age 必须为整数秒'); attrs.maxAgeSec=null; }
      else attrs.maxAgeSec=parseInt(v,10);
    } else if(kl==='domain'){ attrs.domain=v.replace(/^\./,''); }
    else if(kl==='path'){ attrs.path=v; if(v && v.charAt(0)!=='/') issues.push('Path 应以 / 开头'); }
    else if(kl==='samesite'){
      var sv=v.toLowerCase();
      if(['strict','lax','none'].indexOf(sv)<0){ issues.push('SameSite 取值须为 Strict/Lax/None'); attrs.sameSite=v; }
      else attrs.sameSite=sv.charAt(0).toUpperCase()+sv.slice(1);
    }
    else if(kl==='secure'){ attrs.secure=true; }
    else if(kl==='httponly'){ attrs.httpOnly=true; }
    else if(kl==='partitioned'){ attrs.partitioned=true; }
    else { attrs[k]=v; }
  }
  if(!name) issues.push('缺少 cookie 名');
  if(attrs.sameSite==='None' && !attrs.secure) issues.push('SameSite=None 必须配合 Secure，否则会被现代浏览器拒绝');
  if(attrs.secure===true && attrs.maxAgeSec==null && attrs.expiresTs==null) warnings.push('会话 cookie：浏览器关闭后即失效（无 Expires/Max-Age）');
  if(attrs.domain && attrs.domain.indexOf('.')<0) warnings.push('Domain 无内嵌点，多数浏览器会拒绝');
  if(attrs.expiresTs!=null && attrs.expiresTs<=Date.now()) warnings.push('Expires 已过期');
  return {name:name, value:value, attrs:attrs, issues:issues, warnings:warnings, valid:issues.length===0};
}
function buildSetCookie(o){
  o=o||{};
  var name=String(o.name||'').trim();
  if(!name) return {error:'缺少 cookie 名'};
  var value=String(o.value==null?'':o.value);
  var parts=[name+'='+value];
  var days=parseFloat(o.days);
  if(!isNaN(days)&&days>0){
    var ms=Date.now()+days*86400000;
    parts.push('Expires='+new Date(ms).toUTCString());
    parts.push('Max-Age='+Math.round(days*86400));
  } else if(o.maxAgeSec!=null&&o.maxAgeSec!==''){
    var ma=parseInt(o.maxAgeSec,10);
    if(!isNaN(ma)) parts.push('Max-Age='+ma);
  }
  if(o.domain) parts.push('Domain='+String(o.domain).replace(/^\./,''));
  if(o.path) parts.push('Path='+o.path);
  if(o.httpOnly) parts.push('HttpOnly');
  if(o.secure) parts.push('Secure');
  var ss=String(o.sameSite||'');
  if(ss) parts.push('SameSite='+ss);
  if(o.partitioned) parts.push('Partitioned');
  var issues=[];
  if(ss==='None'&&!o.secure) issues.push('SameSite=None 需配合 Secure');
  return {header:parts.join('; '), issues:issues};
}
function domainMatch(host, domain){
  host=String(host||'').toLowerCase();
  domain=String(domain||'').toLowerCase().replace(/^\./,'');
  if(!host||!domain) return false;
  if(host===domain) return true;
  return host.lastIndexOf('.'+domain)===host.length-domain.length-1;
}
function pathMatch(reqPath, cookiePath){
  reqPath=String(reqPath||'/');
  cookiePath=String(cookiePath||'/');
  if(cookiePath==='') cookiePath='/';
  if(reqPath===cookiePath) return true;
  if(reqPath.lastIndexOf(cookiePath,0)===0){
    if(cookiePath.charAt(cookiePath.length-1)==='/') return true;
    if(reqPath.charAt(cookiePath.length)==='/') return true;
  }
  return false;
}
function cookieReport(cookieStr, host, reqPath, isSecure){
  var c=parseSetCookie(cookieStr);
  var reasons=[];
  var send=true;
  if(!c.valid){ send=false; reasons.push('Set-Cookie 本身不合法：'+(c.issues[0]||'未知问题')); }
  var a=c.attrs;
  if(send && a.domain && !domainMatch(host, a.domain)){ send=false; reasons.push('Domain 不匹配：'+host+' 不在 '+a.domain+' 下'); }
  if(send && a.path && !pathMatch(reqPath, a.path||'/')){ send=false; reasons.push('Path 不匹配：'+reqPath+' 不在 '+a.path+' 下'); }
  if(send && a.secure && !isSecure){ send=false; reasons.push('Secure cookie 不会经明文 http:// 发送'); }
  if(send && a.expiresTs!=null && a.expiresTs<=Date.now()){ send=false; reasons.push('Cookie 已过期'); }
  if(send && a.maxAgeSec!=null && a.maxAgeSec<=0){ send=false; reasons.push('Max-Age<=0，浏览器将删除该 cookie'); }
  if(send && a.sameSite==='None' && !a.secure){ send=false; reasons.push('SameSite=None 未配 Secure，会被拒绝'); }
  if(send) reasons.push('满足全部匹配规则，该请求会携带此 cookie');
  return {name:c.name, sendable:send, reasons:reasons, parsed:c};
}
var EXPORTS={parseCookiePairs:parseCookiePairs, parseSetCookie:parseSetCookie, buildSetCookie:buildSetCookie, domainMatch:domainMatch, pathMatch:pathMatch, cookieReport:cookieReport};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.CookieForgePure = EXPORTS; }
